#!/usr/bin/env python3
"""Generates src/lib/font_ja.c: 12x12 bitmap glyphs for the Japanese text of gfx (kana, punctuation,
full-width forms and the JIS X 0208 kanji) rendered from IPAGothic (IPA Font License v1.0, see
licenses/). Needs Pillow and the IPAGothic font; the generated file is committed, so building Sprint
does not need either.

    python3 tools/genfont.py /usr/share/fonts/opentype/ipafont-gothic/ipag.ttf > src/lib/font_ja.c
"""
import sys
from PIL import Image, ImageDraw, ImageFont

path = sys.argv[1]
font = ImageFont.truetype(path, 12)


def cps():
    out = set()
    out.update(range(0x3000, 0x3040))    # CJK symbols and punctuation
    out.update(range(0x3041, 0x3097))    # hiragana
    out.update(range(0x30A1, 0x30FF))    # katakana
    out.update(range(0xFF01, 0xFF5F))    # full-width ASCII
    out.update([0xFFE3, 0xFFE5, 0x2010, 0x2015, 0x2018, 0x2019, 0x201C, 0x201D, 0x2025, 0x2026, 0x2190, 0x2191, 0x2192, 0x2193,
                0x25A0, 0x25A1, 0x25B2, 0x25B3, 0x25BC, 0x25BD, 0x25C6, 0x25C7, 0x25CB, 0x25CF, 0x2605, 0x2606, 0x00B0, 0x00D7, 0x00F7])
    for row in range(0x21, 0x75):         # JIS X 0208 rows 1-84 (symbols, kanji level 1 and 2)
        for col in range(0x21, 0x7F):
            try:
                ch = bytes([row | 0x80, col | 0x80]).decode('euc_jp')
            except UnicodeDecodeError:
                continue
            if len(ch) == 1 and ord(ch) >= 0x3000 and ord(ch) not in range(0xFF61, 0xFFA0):
                out.add(ord(ch))
    return sorted(c for c in out if not (0xFF61 <= c < 0xFFA0))


def glyph(cp):
    im = Image.new('1', (14, 14), 1)
    d = ImageDraw.Draw(im)
    d.fontmode = '1'
    d.text((0, 0), chr(cp), font=font, fill=0)
    rows = []
    for y in range(12):
        v = 0
        for x in range(12):
            if im.getpixel((x, y)) == 0:
                v |= 1 << x
        rows.append(v)
    return rows


codes = []
data = []
for c in cps():
    g = glyph(c)
    if c != 0x3000 and not any(g):
        continue
    codes.append(c)
    bits = 0
    nb = 0
    packed = []
    for r in g:
        bits |= r << nb
        nb += 12
        while nb >= 8:
            packed.append(bits & 255)
            bits >>= 8
            nb -= 8
    assert nb == 0
    data.append(packed)

print('/* Generated by tools/genfont.py - do not edit.')
print(' * 12x12 glyphs rendered from IPAGothic (c) 2007-2011 Information-technology Promotion Agency, Japan,')
print(' * used under the IPA Font License v1.0 (see licenses/IPA-Font-License-v1.0.txt).')
print(' * Row-major, 12 bits per row (bit 0 = leftmost pixel), 18 bytes per glyph. */')
print('#include "font_ja.h"')
print()
print('const int font_ja_count = %d;' % len(codes))
print('const uint16_t font_ja_code[%d] = {' % len(codes))
for i in range(0, len(codes), 12):
    print('    ' + ','.join('0x%04X' % c for c in codes[i:i + 12]) + ',')
print('};')
print('const uint8_t font_ja_bits[%d][18] = {' % len(codes))
for p in data:
    print('    {' + ','.join(str(b) for b in p) + '},')
print('};')
